from pathlib import Path
from html import escape
import re
root = Path(__file__).resolve().parents[1] / 'site'
home=(root/'index.html').read_text()
header=re.search(r'<a class="skip-link".*?</header>',home,re.S)[0]
header=re.sub(r'href="#(?!main)([^"]+)"',r'href="/#\1"',header)
footer=re.search(r'<footer.*?</footer>',home,re.S)[0]
footer=re.sub(r'href="#([^"]+)"',r'href="/#\1"',footer)
def page(path,title,description,content,noindex=False):
    target=root/path/'index.html'; target.parent.mkdir(parents=True,exist_ok=True)
    url='https://reefsolutions.co/'+str(path).strip('/')+'/'
    target.write_text(f'''<!doctype html><html lang="en-MY"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | REEF Solutions</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{url}"><meta name="theme-color" content="#082B2D">{'<meta name="robots" content="noindex">' if noindex else ''}<meta property="og:title" content="{escape(title,quote=True)} | REEF Solutions"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:image" content="https://reefsolutions.co/assets/social-cover.jpg"><meta property="og:type" content="website"><meta property="og:url" content="{url}"><link rel="icon" href="/assets/reef-mark.svg" type="image/svg+xml"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body>{header}<main id="main">{content}</main>{footer}</body></html>''')
projects=[
('allianz','Allianz Malaysia: 16,400 kWh less every month.','Commercial offices / Kuala Lumpur','Targeted improvements across 13 office floors at Menara Allianz Sentral and Plaza Sentral.','allianz','Menara Allianz Sentral, Kuala Lumpur',
'''<h2>The opportunity</h2><p>Energy consumption was spread across lighting, air conditioning and equipment used in the everyday running of a corporate headquarters. REEF reviewed how those systems were operated, then identified improvements across two buildings.</p><h2>What changed</h2><ul><li><strong>Lighting:</strong> improvements to lighting systems and how they were operated.</li><li><strong>HVAC:</strong> optimisation of air-conditioning operation.</li><li><strong>Building retrofits:</strong> targeted upgrades identified through the assessment.</li><li><strong>Operating routines:</strong> reducing unnecessary running time for printers, water dispensers and air-conditioning units.</li></ul><h2>The reported results</h2><p>REEF’s company profiles report an average reduction of <strong>16,400 kWh per month</strong>, with average monthly financial savings of approximately <strong>RM 8,900</strong>. Project follow-up notes state that improvements appeared on the electricity bill the month after implementation.</p><p>The engagement used a shared-savings arrangement. That historical structure does not imply that other projects qualify for the same commercial terms.</p><h2>What the numbers mean for your building</h2><p>These are historical results for this engagement. A new property needs its own assessment, baseline and investment case. Savings depend on equipment, tariffs, occupancy and operating conditions.</p><p>The client’s baseline consumption is confidential. We do not publish an energy-reduction percentage or extrapolate this result to other buildings.</p>''',
'<strong>Project scope</strong><p>13 office floors · 2 buildings</p><strong>Average monthly reduction</strong><p>16,400 kWh</p><strong>Average monthly savings</strong><p>Approximately RM 8,900</p><p>Source: REEF company profiles and project follow-up notes. Historical reported results; not a savings guarantee.</p>'),
('commons','The Commons, EduCity.','Solar + water / Iskandar, Johor','Renewable generation and water systems designed around an educational space.','commons','Bifacial solar tree at The Commons, EduCity',
'''<h2>Energy and water, considered together</h2><p>The Commons brought solar generation and rainwater harvesting into the operation of two buildings at EduCity, Iskandar.</p><h2>Scope of work</h2><ul><li>A bifacial solar tree and supplementary rooftop panels to power lighting, fans and other electrical loads.</li><li>Rainwater collection and storage.</li><li>Filtration to support the site’s water needs.</li></ul><h2>Practical systems in a shared space</h2><p>The project illustrates REEF’s experience integrating resource systems around real building uses. The company profile documents the installed scope. Project-specific cost savings and payback figures are not published here.</p>''',
'<strong>Sector</strong><p>Education / shared campus space</p><strong>Location</strong><p>EduCity, Iskandar, Johor</p><strong>Systems</strong><p>Solar generation, rainwater harvesting and filtration</p>'),
('datai','The Datai Langkawi.','Hospitality / Langkawi','A practical framework for resource efficiency across a luxury resort.','datai','The Datai Langkawi resort in its rainforest setting',
'''<h2>A whole-property view</h2><p>A resort’s resource needs extend across buildings, infrastructure, guest services and everyday operations. REEF’s documented work at The Datai Langkawi addresses those systems through sustainability assessment and management planning.</p><h2>Assessment and management scope</h2><ul><li>Energy efficiency.</li><li>Water efficiency.</li><li>Waste reduction and resource recovery.</li><li>Operational practices and community engagement.</li></ul><h2>From assessment to priorities</h2><p>The work creates a framework for identifying improvements and embedding better practices in day-to-day operations.</p><p>This project is presented for its assessment and management scope. No measured reduction in the resort’s energy or water consumption is claimed here.</p>''',
'<strong>Sector</strong><p>Luxury hospitality</p><strong>Location</strong><p>Langkawi, Malaysia</p><strong>Scope</strong><p>Sustainability assessment and management systems</p>'),
('earthship','Earthship Malaysia.','Integrated resource systems / Malaysia','Bringing independent energy and water systems into community buildings.','earthship','Earthship Malaysia community buildings',
'''<h2>Designed as one system</h2><p>The documented Earthship Malaysia project comprises two houses and a community centre, combining building design with resource systems.</p><h2>Integrated scope</h2><ul><li>Solar energy generation.</li><li>Rainwater harvesting and greywater recycling.</li><li>On-site sewage treatment.</li><li>Passive temperature control and food planters.</li></ul><h2>Experience that informs our work</h2><p>The project demonstrates experience in coordinating energy, water and building operation. We apply that same whole-system perspective to commercial property assessments, with solutions tailored to each site.</p>''',
'<strong>Built scope</strong><p>Two houses and a community centre</p><strong>Systems</strong><p>Solar, rainwater, greywater, sewage treatment and passive design</p>')]
for slug,title,category,lead,img,alt,body,facts in projects:
    page(Path('projects')/slug,title,lead,f'''<section class="article-hero wrap"><a class="breadcrumb" href="/#projects">← Selected projects</a><p class="eyebrow">{category}</p><h1>{title}</h1><p class="article-lead">{lead}</p></section><section class="wrap article-grid" style="padding-bottom:90px"><div class="article-body">{body}<div class="article-cta"><h2>What could change in your building?</h2><p>Start with an assessment of your systems, operating patterns and priorities.</p><a class="button" href="/#contact">Book an Energy Assessment <span aria-hidden="true">↗</span></a></div></div><aside class="article-aside"><img src="/assets/{img}.webp" alt="{alt}" width="700" height="600">{facts}</aside></section>''')
page(Path('thank-you'),'Thank you for your enquiry','Your energy assessment enquiry has been submitted.', '''<section class="wrap simple-page"><div class="success-icon" aria-hidden="true">✓</div><p class="eyebrow">Enquiry received</p><h1>Thank you.<br>Let’s understand your building.</h1><p>Your enquiry has been submitted. The REEF team will review your property details and contact you to discuss the fit, information needed and assessment scope.</p><p>No assessment or project commitment has been made at this stage.</p><a class="button" href="/">Back to REEF <span aria-hidden="true">↗</span></a></section>''',True)
page(Path('privacy'),'Enquiry privacy notice','How REEF handles information submitted through this website.', '''<section class="wrap simple-page"><p class="eyebrow">Website enquiries</p><h1>How we handle your information.</h1><p>This notice covers enquiries submitted to Resource Efficiency Consulting Sdn. Bhd., trading as REEF Solutions, through this website.</p><h2>What you share</h2><p>The assessment form collects your name, company, work email, role, building type, location, approximate energy spend and description of your requirements. Please do not include confidential building records, financial account details or other sensitive information in the initial enquiry.</p><h2>Why we use it</h2><p>We use these details to respond, assess whether our services fit your requirements and discuss a possible assessment. Submitting an enquiry does not sign you up for a marketing list.</p><h2>How enquiries are processed</h2><p>The website and form are hosted by Netlify. Form submissions are processed and stored through Netlify’s services and may be processed outside Malaysia. REEF uses the submitted details to manage your enquiry.</p><h2>Your questions and requests</h2><p>To ask about the information you have provided, request a correction or request deletion, contact <a href="mailto:reefsolutions.co@gmail.com">reefsolutions.co@gmail.com</a>.</p><h2>Links to other websites</h2><p>External links, including social profiles, are subject to the privacy practices of those services. This website does not embed advertising trackers or third-party analytics.</p></section>''')
page(Path('credits'),'Photo credits','Sources for the photography used on the REEF website.', '''<section class="wrap simple-page"><p class="eyebrow">Real places. Documented sources.</p><h1>Photography credits.</h1><h2>Kuala Lumpur architecture</h2><p>Hero photograph by <a href="https://unsplash.com/@nazahery" target="_blank" rel="noopener noreferrer">Nazarizal Mohammad</a>, via <a href="https://unsplash.com/photos/high-rise-building-during-daytime-9neA6wcJVPc" target="_blank" rel="noopener noreferrer">Unsplash</a>, used under the <a href="https://unsplash.com/license" target="_blank" rel="noopener noreferrer">Unsplash License</a>. Cropped for responsive display. This is illustrative architecture photography; the pictured buildings are not presented as REEF projects.</p><h2>REEF project photography</h2><p>The Datai Langkawi, The Commons solar tree, Earthship Malaysia, rooftop solar and water-system photographs were recovered from REEF’s existing company profile. The Allianz tower photograph and team portraits were recovered from REEF’s existing production website.</p><p>Project images illustrate the documented project scope. They are not used to imply unsupported energy savings or other performance claims.</p></section>''')
page(Path('404'),'Page not found','The requested page could not be found.', '''<section class="wrap simple-page"><p class="eyebrow">404 / Page not found</p><h1>Let’s get you<br>back on track.</h1><p>The page you requested is not available.</p><a class="button" href="/">Back to REEF <span aria-hidden="true">↗</span></a></section>''',True)
(root/'404.html').write_text((root/'404/index.html').read_text())
(root/'robots.txt').write_text('User-agent: *\nAllow: /\nDisallow: /thank-you\nSitemap: https://reefsolutions.co/sitemap.xml\n')
urls=['','projects/allianz/','projects/commons/','projects/datai/','projects/earthship/','privacy/','credits/']
(root/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://reefsolutions.co/'+u+'</loc></url>' for u in urls)+'</urlset>')
print('Built project pages, privacy, credits, thank-you, 404 and sitemap.')
